fn is_palindrome(text: Vec<char>) -> bool {
    let n = text.len();
    
    for i in 0..n / 2 {
        let left_char = text[i];
        let right_char = text[n - 1 - i];
        
        // Convert to lowercase for ASCII uppercase letters only
        let left_lower = if left_char >= 'A' && left_char <= 'Z' {
            (left_char as u8 + 32) as char
        } else {
            left_char
        };
        
        let right_lower = if right_char >= 'A' && right_char <= 'Z' {
            (right_char as u8 + 32) as char
        } else {
            right_char
        };
        
        if left_lower != right_lower {
            return false;
        }
    }
    
    true
}